+/// <summary>
+/// Extractive summarizer that scores sentences by word frequency
+/// and returns the top-ranked ones in their original order.
+/// </summary>
+public partial class DocumentSummarizationService : IDocumentSummarizationService
+{
+    private static readonly HashSet<string> StopWords = new(StringComparer.OrdinalIgnoreCase)
+    {
+        "a","an","the","and","or","but","is","are","was","were","be","been","being",
+        "have","has","had","do","does","did","will","would","shall","should","may",
+        "might","can","could","in","on","at","to","for","of","with","by","from",
+        "that","this","it","its","he","she","they","we","you","i","me","my","his",
+        "her","our","their","not","no","so","if","as","up","out","about","into",
+        "than","then","also","very","just","more","most","some","any","all","each"
+    };
+
+    public (string Summary, int OriginalCount, int SummaryCount) Summarize(string text, int maxSentences)
+    {
+        var sentences = SplitSentences(text);
+
+        if (sentences.Count <= maxSentences)
+        {
+            var joined = string.Join(" ", sentences);
+            return (joined, sentences.Count, sentences.Count);
+        }
+
+        var wordFrequencies = BuildWordFrequencies(sentences);
+        var scores = ScoreSentences(sentences, wordFrequencies);
+
+        // Pick the top-scored sentences, then reorder by original position.
+        var topIndices = scores
+            .Select((score, index) => (score, index))
+            .OrderByDescending(x => x.score)
+            .Take(maxSentences)
+            .Select(x => x.index)
+            .OrderBy(x => x)
+            .ToList();
+
+        var summary = string.Join(" ", topIndices.Select(i => sentences[i]));
+        return (summary, sentences.Count, topIndices.Count);
+    }
+
+    private static List<string> SplitSentences(string text)
+    {
+        return SentenceRegex()
+            .Split(text)
+            .Select(s => s.Trim())
+            .Where(s => s.Length > 0)
+            .ToList();
+    }
+
+    private static Dictionary<string, int> BuildWordFrequencies(List<string> sentences)
+    {
+        var freq = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
+        foreach (var sentence in sentences)
+        {
+            foreach (var word in WordRegex().Matches(sentence).Select(m => m.Value))
+            {
+                if (word.Length > 1 && !StopWords.Contains(word))
+                {
+                    freq[word] = freq.GetValueOrDefault(word) + 1;
+                }
+            }
+        }
+        return freq;
+    }
